import"./style-BPSCewVD.js";const e=document.querySelector("#license-content");async function s(){try{const t=await fetch("./LICENCE");if(!t.ok)throw new Error(`License request failed with status ${t.status}`);const o=(await t.text()).trim().split(/\r?\n\s*\r?\n/);e.replaceChildren();for(const[a,c]of o.entries()){if(a===0){const n=document.createElement("h2");n.textContent=c.trim(),e.append(n);continue}if(c.match(/^Section \d+ – .+\.$/)){const n=document.createElement("h3");n.textContent=c.trim(),e.append(n);continue}const r=document.createElement("p");r.textContent=c.trim(),e.append(r)}}catch(t){console.error("Unable to load the license text.",t),e.replaceChildren();const o=document.createElement("p");o.textContent="Le texte de la licence n’a pas pu être chargé. Vous pouvez le consulter dans le fichier LICENCE du projet.",e.append(o)}}s();
